namespace AM.TribonAutomationProbe.Core;

public static class GeometryContractValidator
{
    public static void ValidateDetectionResponse(GeometryObjectDetectionResponse value)
    {
        if (value is null) throw Invalid("detection response is required");
        Required(value, value.Objects, "objects"); ValidateSucceededHeader(value.SchemaVersion, value.Status); if (string.IsNullOrWhiteSpace(value.RequestId) || string.IsNullOrWhiteSpace(value.Scope) || value.Diagnostics is null || value.Diagnostics.CapturedContourCount < 0 || value.Diagnostics.AssignedUniqueContourCount < 0 || value.Diagnostics.UnassignedContourCount < 0 || value.Diagnostics.ConflictHandleCount < 0 || value.Diagnostics.ParseFailureCount < 0) throw Invalid("Invalid detection header"); Rect(value.DrawingExtent); var ids = new HashSet<string>(StringComparer.Ordinal); var handles = new HashSet<string>(StringComparer.Ordinal); foreach (var o in value.Objects) { if (string.IsNullOrWhiteSpace(o.RuntimeObjectId) || !ids.Add(o.RuntimeObjectId) || !Enum.IsDefined(o.Category) || string.IsNullOrWhiteSpace(o.Confidence) || o.Features is null || o.GeometryCount < 0 || o.GeometryHandles is null || o.SeedHandles is null || o.GeometryHandles.Count != o.GeometryCount || o.GeometryHandles.Any(string.IsNullOrWhiteSpace) || o.GeometryHandles.Distinct(StringComparer.Ordinal).Count() != o.GeometryHandles.Count || !o.GeometryHandles.All(handles.Add) || o.SeedHandles.Any(string.IsNullOrWhiteSpace) || o.SeedHandles.Distinct(StringComparer.Ordinal).Count() != o.SeedHandles.Count) throw Invalid("Invalid detection object"); Rect(o.Extent); } if (value.Diagnostics.AssignedUniqueContourCount != handles.Count || value.Diagnostics.CapturedContourCount != handles.Count + value.Diagnostics.UnassignedContourCount) throw Invalid("Detection diagnostics mismatch");
    }
    public static void ValidateLabelInspectionResponse(GeometryLabelInspectionResponse value) { if (value is null) throw Invalid("label response is required"); Required(value, value.Labels, "labels"); ValidateSucceededHeader(value.SchemaVersion, value.Status); if (string.IsNullOrWhiteSpace(value.RequestId) || value.Diagnostics is null || value.Diagnostics.DuplicateTextCount < 0 || value.Diagnostics.ExtentReadFailureCount < 0 || value.Diagnostics.TextPropertyFailureCount < 0) throw Invalid("Invalid label response"); var ids = new HashSet<string>(StringComparer.Ordinal); foreach (var x in value.Labels) { if (string.IsNullOrWhiteSpace(x.RuntimeHandle) || !ids.Add(x.RuntimeHandle) || string.IsNullOrWhiteSpace(x.Text)) throw Invalid("Invalid label"); Rect(x.Extent); } }
    public static void ValidateDisplayIdMap(GeometryObjectDisplayIdMap value, IReadOnlyList<DetectedGeometryObject> objects) { if (value is null || objects is null) throw Invalid("display id map is required"); Required(value, value.Items, "display ids"); if (objects.Select(x => x.RuntimeObjectId).Distinct(StringComparer.Ordinal).Count() != objects.Count || value.Items.Count != objects.Count || value.Items.Any(x => string.IsNullOrWhiteSpace(x.RuntimeObjectId) || string.IsNullOrWhiteSpace(x.DisplayId) || !objects.Any(o => o.RuntimeObjectId == x.RuntimeObjectId && o.Category == x.Category) || x.PersistentAcrossGeometryChanges) || value.Items.Select(x => x.DisplayId).Distinct(StringComparer.Ordinal).Count() != value.Items.Count || value.Items.Select(x => x.RuntimeObjectId).Distinct(StringComparer.Ordinal).Count() != value.Items.Count) throw Invalid("Invalid display id map"); }
    public static void ValidateMatchResult(GeometryObjectLabelMatchResult value) { if (value is null) throw Invalid("match result is required"); Required(value, value.Matches, "matches"); if (value.OtherTexts is null || value.Diagnostics is null || value.Matches.Select(x => x.Identity.RuntimeObjectId).Distinct(StringComparer.Ordinal).Count() != value.Matches.Count || value.Matches.Select(x => x.Identity.DisplayId).Distinct(StringComparer.Ordinal).Count() != value.Matches.Count || value.Matches.Any(x => x.Object is null || x.Identity.RuntimeObjectId != x.Object.RuntimeObjectId || x.Identity.Category != x.Object.Category || !ValidRect(x.Object.Extent) || x.SameText is null || x.SameText.Any(y => string.IsNullOrWhiteSpace(y.RuntimeHandle) || string.IsNullOrWhiteSpace(y.Text) || !ValidRect(y.Extent)) || x.SameText.Select(y => y.RuntimeHandle).Distinct(StringComparer.Ordinal).Count() != x.SameText.Count || (x.Label is not null && (string.IsNullOrWhiteSpace(x.Label.RuntimeHandle) || string.IsNullOrWhiteSpace(x.Label.Text) || !ValidRect(x.Label.Extent))) || (x.Status == GeometryLabelMatchStatus.Matched && (x.Label is null || x.SameText.Count != 1 || x.SameText[0].RuntimeHandle != x.Label.RuntimeHandle)) || (x.Status == GeometryLabelMatchStatus.Missing && (x.Label is not null || x.SameText.Count != 0)) || (x.Status == GeometryLabelMatchStatus.Duplicate && (x.Label is not null || x.SameText.Count < 2)) || (x.Status == GeometryLabelMatchStatus.TextConflict && (x.Label is null || x.SameText.Count != 1))) || value.OtherTexts.Any(x => string.IsNullOrWhiteSpace(x.RuntimeHandle) || string.IsNullOrWhiteSpace(x.Text) || !ValidRect(x.Extent)) || value.OtherTexts.Select(x => x.RuntimeHandle).Distinct(StringComparer.Ordinal).Count() != value.OtherTexts.Count || value.OtherTexts.Any(x => value.Matches.Any(m => m.Status == GeometryLabelMatchStatus.Matched && m.Label?.RuntimeHandle == x.RuntimeHandle))) throw Invalid("Invalid match result"); if (value.Diagnostics.MissingCount != value.Matches.Count(x => x.Status == GeometryLabelMatchStatus.Missing) || value.Diagnostics.DuplicateCount != value.Matches.Count(x => x.Status == GeometryLabelMatchStatus.Duplicate) || value.Diagnostics.TextConflictCount != value.Matches.Count(x => x.Status == GeometryLabelMatchStatus.TextConflict)) throw Invalid("Match diagnostics mismatch"); }
    public static void ValidateAuditResult(GeometryObjectLabelAuditResult value) { if (value is null) throw Invalid("audit result is required"); Required(value, value.Items, "audit items"); CheckHeader(value.SchemaVersion, value.Status); if (double.IsNaN(value.AreaTolerance) || double.IsInfinity(value.AreaTolerance) || value.AreaTolerance < 0) throw Invalid("Invalid audit tolerance"); var decisions = new[] { "needs_relayout", "clear_preferred_side", "clear_non_preferred_side", "blocked_missing", "blocked_duplicate", "blocked_text_conflict" }; if (value.Items.Any(x => string.IsNullOrWhiteSpace(x.OperationId) || string.IsNullOrWhiteSpace(x.RuntimeObjectId) || string.IsNullOrWhiteSpace(x.DisplayId) || !decisions.Contains(x.Decision) || !ValidRect(x.ObjectExtent) || (x.LabelExtent is not null && !ValidRect(x.LabelExtent)) || double.IsNaN(x.OwnObjectOverlapArea) || double.IsInfinity(x.OwnObjectOverlapArea) || x.OwnObjectOverlapArea < 0 || double.IsNaN(x.OwnObjectClearance) || double.IsInfinity(x.OwnObjectClearance) || x.OwnObjectClearance < 0 || x.OtherObjectOverlapIds is null || x.TargetLabelOverlapIds is null || x.OtherTextOverlapHandles is null || x.OtherObjectOverlapIds.Any(string.IsNullOrWhiteSpace) || x.TargetLabelOverlapIds.Any(string.IsNullOrWhiteSpace) || x.OtherTextOverlapHandles.Any(string.IsNullOrWhiteSpace) || x.OtherObjectOverlapIds.Distinct(StringComparer.Ordinal).Count() != x.OtherObjectOverlapIds.Count || x.TargetLabelOverlapIds.Distinct(StringComparer.Ordinal).Count() != x.TargetLabelOverlapIds.Count || x.OtherTextOverlapHandles.Distinct(StringComparer.Ordinal).Count() != x.OtherTextOverlapHandles.Count || (x.MatchStatus == GeometryLabelMatchStatus.Matched && (string.IsNullOrWhiteSpace(x.RuntimeLabelHandle) || string.IsNullOrWhiteSpace(x.Text) || x.LabelExtent is null)) || (x.MatchStatus == GeometryLabelMatchStatus.Missing && x.Decision != "blocked_missing") || (x.MatchStatus == GeometryLabelMatchStatus.Duplicate && x.Decision != "blocked_duplicate") || (x.MatchStatus == GeometryLabelMatchStatus.TextConflict && x.Decision != "blocked_text_conflict")) || value.Items.Select(x => x.OperationId).Distinct(StringComparer.Ordinal).Count() != value.Items.Count || value.Items.Select(x => x.RuntimeObjectId).Distinct(StringComparer.Ordinal).Count() != value.Items.Count || value.Items.Select(x => x.DisplayId).Distinct(StringComparer.Ordinal).Count() != value.Items.Count || value.ObjectCount != value.Items.Count || value.MatchedLabelCount != value.Items.Count(x => x.MatchStatus == GeometryLabelMatchStatus.Matched) || value.MissingLabelCount != value.Items.Count(x => x.MatchStatus == GeometryLabelMatchStatus.Missing) || value.DuplicateLabelCount != value.Items.Count(x => x.MatchStatus == GeometryLabelMatchStatus.Duplicate) || value.TextConflictCount != value.Items.Count(x => x.MatchStatus == GeometryLabelMatchStatus.TextConflict) || value.OwnObjectOverlapCount != value.Items.Count(x => x.OwnObjectOverlapArea > value.AreaTolerance) || value.OtherObjectOverlapLabelCount != value.Items.Count(x => x.OtherObjectOverlapIds.Count > 0) || value.TargetLabelOverlapLabelCount != value.Items.Count(x => x.TargetLabelOverlapIds.Count > 0) || value.OtherTextOverlapLabelCount != value.Items.Count(x => x.OtherTextOverlapHandles.Count > 0) || value.NeedsRelayoutCount != value.Items.Count(x => x.Decision == "needs_relayout") || value.ClearPreferredSideCount != value.Items.Count(x => x.Decision == "clear_preferred_side") || value.ClearNonPreferredSideCount != value.Items.Count(x => x.Decision == "clear_non_preferred_side") || (value.Items.Any(x => x.Decision.StartsWith("blocked_", StringComparison.Ordinal)) != (value.Status == "blocked"))) throw Invalid("Audit summary mismatch"); }
    public static void ValidatePlan(GeometryObjectLabelPlan value) { if (value is null) throw Invalid("plan is required"); Required(value, value.Items, "plan items"); Required(value, value.Moves, "plan moves"); if (!ValidRect(value.DrawingExtent) || value.SchemaVersion != "1.0" || value.TaskType != "create_geometry_object_label_layout" || value.Mode != "dry-run" || value.DrawingWritePerformed || value.InitialConflictCount < 0 || value.RemainingConflictCount < 0 || !new[] { "blocked", "no_changes_required", "planned", "no_solution" }.Contains(value.Status) || value.Items.Any(x => string.IsNullOrWhiteSpace(x.OperationId) || string.IsNullOrWhiteSpace(x.RuntimeObjectId) || string.IsNullOrWhiteSpace(x.DisplayId) || string.IsNullOrWhiteSpace(x.ExpectedText) || x.CurrentConflictCount < 0 || x.DesiredConflictCount < 0 || double.IsNaN(x.Dx) || double.IsInfinity(x.Dx) || double.IsNaN(x.Dy) || double.IsInfinity(x.Dy) || (x.CurrentExtent is not null && !ValidRect(x.CurrentExtent)) || (x.DesiredExtent is not null && !ValidRect(x.DesiredExtent))) || value.Items.Select(x => x.OperationId).Distinct(StringComparer.Ordinal).Count() != value.Items.Count || value.Items.Select(x => x.RuntimeObjectId).Distinct(StringComparer.Ordinal).Count() != value.Items.Count || value.KeepCount != value.Items.Count(x => x.Action == GeometryLabelPlanAction.KeepCurrent) || value.MoveCount != value.Items.Count(x => x.Action == GeometryLabelPlanAction.Move) || value.BlockedCount != value.Items.Count(x => x.Action == GeometryLabelPlanAction.Blocked) || value.MoveCount != value.Moves.Count || value.Moves.Select(x => x.OperationId).Distinct(StringComparer.Ordinal).Count() != value.Moves.Count || value.Moves.Select(x => x.RuntimeHandle).Distinct(StringComparer.Ordinal).Count() != value.Moves.Count || value.Moves.Any(x => string.IsNullOrWhiteSpace(x.OperationId) || string.IsNullOrWhiteSpace(x.RuntimeHandle) || string.IsNullOrWhiteSpace(x.ExpectedText) || double.IsNaN(x.Dx) || double.IsInfinity(x.Dx) || double.IsNaN(x.Dy) || double.IsInfinity(x.Dy))) throw Invalid("Invalid plan contract"); ValidatePlanState(value); foreach (var x in value.Moves) { Rect(x.ExpectedExtent); Rect(x.DesiredExtent); if (!x.ExpectedExtent.Move(x.Dx, x.Dy).ApproximatelyEquals(x.DesiredExtent)) throw Invalid("Plan move mismatch"); } }
    private static void ValidatePlanState(GeometryObjectLabelPlan x) { var moveItems = x.Items.Where(i => i.Action == GeometryLabelPlanAction.Move).ToArray(); var blockedItems = x.Items.Count(i => i.Action == GeometryLabelPlanAction.Blocked); if (x.Status == "planned" && (x.Moves.Count == 0 || moveItems.Length != x.Moves.Count || x.BlockedCount != 0 || blockedItems != 0 || x.RemainingConflictCount != 0 || !x.RequiresAllowWrite) || x.Status == "no_changes_required" && (x.Moves.Count != 0 || moveItems.Length != 0 || blockedItems != 0 || x.InitialConflictCount != 0 || x.RemainingConflictCount != 0 || x.MoveCount != 0 || x.BlockedCount != 0 || x.RequiresAllowWrite) || x.Status == "blocked" && (x.Moves.Count != 0 || moveItems.Length != 0 || x.MoveCount != 0 || blockedItems == 0 || !x.RequiresAllowWrite) || x.Status == "no_solution" && (x.Moves.Count != 0 || moveItems.Length != 0 || x.MoveCount != 0 || x.RemainingConflictCount <= 0 || x.RequiresAllowWrite)) throw Invalid("Invalid plan status combination"); foreach (var item in moveItems) { var moves = x.Moves.Where(m => m.OperationId == item.OperationId).ToArray(); if (moves.Length != 1 || item.RuntimeLabelHandle != moves[0].RuntimeHandle || item.ExpectedText != moves[0].ExpectedText || item.CurrentExtent is null || item.DesiredExtent is null || !item.CurrentExtent.ApproximatelyEquals(moves[0].ExpectedExtent) || !item.DesiredExtent.ApproximatelyEquals(moves[0].DesiredExtent) || Math.Abs(item.Dx - moves[0].Dx) > .01 || Math.Abs(item.Dy - moves[0].Dy) > .01 || item.DesiredConflictCount != 0) throw Invalid("Plan item and move mismatch"); } foreach (var item in x.Items.Where(i => i.Action == GeometryLabelPlanAction.KeepCurrent)) if (item.CurrentExtent is null || item.DesiredExtent is null || !item.CurrentExtent.ApproximatelyEquals(item.DesiredExtent) || Math.Abs(item.Dx) > .01 || Math.Abs(item.Dy) > .01 || item.DesiredConflictCount != item.CurrentConflictCount) throw Invalid("Invalid keep item"); foreach (var item in x.Items.Where(i => i.Action == GeometryLabelPlanAction.Blocked)) if (item.DesiredExtent is not null || Math.Abs(item.Dx) > .01 || Math.Abs(item.Dy) > .01) throw Invalid("Invalid blocked item"); }
    private static void ValidateSucceededHeader(string schema, string status) { if (schema != "1.0" || status != "succeeded") throw Invalid("Invalid contract header"); }
    private static void CheckHeader(string schema, string status) { if (schema != "1.0" || (status != "succeeded" && status != "blocked")) throw Invalid("Invalid contract header"); }
    private static bool ValidRect(LayoutRectangle x) => !(double.IsNaN(x.X1) || double.IsNaN(x.Y1) || double.IsNaN(x.X2) || double.IsNaN(x.Y2) || double.IsInfinity(x.X1) || double.IsInfinity(x.Y1) || double.IsInfinity(x.X2) || double.IsInfinity(x.Y2) || x.X2 < x.X1 || x.Y2 < x.Y1);
    private static void Rect(LayoutRectangle x) { if (!ValidRect(x)) throw Invalid("Invalid rectangle"); }
    private static void Required<T>(object owner, T? value, string name) where T : class { if (value is null) throw Invalid(name + " is required"); }
    private static ProbeException Invalid(string message) => new(ProbeErrorCodes.InvalidMessage, message, "validation");
}
